const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because my new smartphone suddenly stopped working yesterday.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.708625},{"speaker":"B","text":"Good morning and I am very sorry to hear about that trouble.","position":2,"audioStartSeconds":4.908625,"audioEndSeconds":8.7925},{"speaker":"A","text":"The screen stays completely black even though the battery is fully charged.","position":3,"audioStartSeconds":8.9925,"audioEndSeconds":13.799958333333333},{"speaker":"B","text":"Did you try holding the power button down for twenty seconds to restart it.","position":4,"audioStartSeconds":13.999958333333334,"audioEndSeconds":18.717208333333332},{"speaker":"A","text":"Yes I did that several times this morning but nothing happened at all.","position":5,"audioStartSeconds":18.917208333333335,"audioEndSeconds":23.388875},{"speaker":"B","text":"That definitely sounds like a hardware defect rather than a software issue.","position":6,"audioStartSeconds":23.588875,"audioEndSeconds":28.46},{"speaker":"A","text":"Can I return this broken device to get a brand new replacement.","position":7,"audioStartSeconds":28.66,"audioEndSeconds":32.83525},{"speaker":"B","text":"We can certainly arrange a free home collection for your faulty phone.","position":8,"audioStartSeconds":33.03525,"audioEndSeconds":37.41670833333333},{"speaker":"A","text":"That sounds very convenient because I cannot visit the store this week.","position":9,"audioStartSeconds":37.616708333333335,"audioEndSeconds":42.062583333333336},{"speaker":"B","text":"Our courier can come to your house tomorrow morning between nine and twelve.","position":10,"audioStartSeconds":42.26258333333333,"audioEndSeconds":47.01775},{"speaker":"A","text":"Tomorrow morning works perfectly for me since I will be working remotely.","position":11,"audioStartSeconds":47.21775,"audioEndSeconds":51.85691666666666},{"speaker":"B","text":"Please make sure you put the phone inside its original box.","position":12,"audioStartSeconds":52.056916666666666,"audioEndSeconds":56.064625},{"speaker":"A","text":"I have kept the original box and all the accessories safely.","position":13,"audioStartSeconds":56.264625,"audioEndSeconds":60.50429166666667},{"speaker":"B","text":"The driver will bring the replacement unit directly to your front door.","position":14,"audioStartSeconds":60.70429166666667,"audioEndSeconds":65.27904166666667},{"speaker":"A","text":"Thank you so much for your quick help with this frustrating problem.","position":15,"audioStartSeconds":65.47904166666666,"audioEndSeconds":69.58129166666667},{"speaker":"B","text":"You are very welcome and have a wonderful rest of your day.","position":16,"audioStartSeconds":69.78129166666666,"audioEndSeconds":73.7015}],"questions":[{"prompt":"What is the main purpose of the customer's call?","options":["To buy a new smartphone.","To report a broken phone.","To ask about phone prices."],"answer":"B","evidenceSentence":1,"evidence":"Good morning because my new smartphone suddenly stopped working yesterday.","explanation":"Khách hàng gọi để thông báo về chiếc điện thoại mới đột nhiên bị hỏng."},{"prompt":"What specific problem does the customer mention?","options":["The screen remains black.","The battery drains too fast.","The speaker makes strange noises."],"answer":"A","evidenceSentence":3,"evidence":"The screen stays completely black even though the battery is fully charged.","explanation":"Khách hàng cho biết màn hình hoàn toàn tối đen dù pin đã được sạc đầy."},{"prompt":"What did the customer do before calling?","options":["Updated the software version.","Tried to restart the device.","Checked the charger cable."],"answer":"B","evidenceSentence":5,"evidence":"Yes I did that several times this morning but nothing happened at all.","explanation":"Khách hàng đã thử khởi động lại điện thoại nhiều lần nhưng không có gì xảy ra."},{"prompt":"What solution does the employee offer?","options":["A free home collection service.","A full refund of the money.","A discount on the next purchase."],"answer":"A","evidenceSentence":8,"evidence":"We can certainly arrange a free home collection for your faulty phone.","explanation":"Nhân viên đề xuất dịch vụ đến tận nhà lấy chiếc điện thoại bị lỗi miễn phí."},{"prompt":"When will the courier arrive at the customer's house?","options":["Tomorrow afternoon.","Tomorrow morning.","Next Monday."],"answer":"B","evidenceSentence":10,"evidence":"Our courier can come to your house tomorrow morning between nine and twelve.","explanation":"Nhân viên giao hàng sẽ đến vào sáng mai từ 9 đến 12 giờ."},{"prompt":"What does the customer need to prepare before the collection?","options":["A printed receipt.","The original box.","An ID card."],"answer":"B","evidenceSentence":12,"evidence":"Please make sure you put the phone inside its original box.","explanation":"Nhân viên yêu cầu khách hàng đặt điện thoại vào hộp ban đầu của nó."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
